<script setup lang="ts">
import {computed,ref} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {useMemberStore} from '../stores/member'
import {safeRedirect} from '../services/member'
import AppHeader from '../components/AppHeader.vue'
import AppIcon from '../components/AppIcon.vue'
const route=useRoute(),router=useRouter(),member=useMemberStore()
const mode=ref<'login'|'register'>(route.query.mode==='register'?'register':'login'),username=ref(''),password=ref(''),nickname=ref(''),show=ref(false),busy=ref(false),error=ref('')
const title=computed(()=>mode.value==='register'?'注册账号':'欢迎回来')
async function submit(){if(busy.value)return;error.value='';busy.value=true;try{await member.authenticate(mode.value,username.value.trim(),password.value,nickname.value.trim()||undefined);password.value='';void router.replace(safeRedirect(route.query.redirect))}catch(cause){error.value=cause instanceof Error?cause.message:'暂时无法登录，请重试'}finally{busy.value=false}}
</script>
<template><AppHeader title="账户" back hide-avatar/><main class="page account-page"><div class="account-heading"><p class="small muted">RentPilot</p><h1>{{ title }}</h1><p>把喜欢的房子，留在自己的清单里。</p></div><form class="rental-form" @submit.prevent="submit"><label class="form-field">用户名<input v-model="username" aria-label="用户名" autocomplete="username" autocapitalize="none" spellcheck="false" required minlength="3" maxlength="24" pattern="[A-Za-z][A-Za-z0-9_]{2,23}" placeholder="字母开头，3–24位字母、数字或下划线" :disabled="busy"/></label><label v-if="mode==='register'" class="form-field">昵称<input v-model="nickname" aria-label="昵称" autocomplete="nickname" maxlength="16" placeholder="怎么称呼你（可选）" :disabled="busy"/></label><label class="form-field">密码<span class="password-input"><input v-model="password" aria-label="密码" :type="show?'text':'password'" :autocomplete="mode==='register'?'new-password':'current-password'" required minlength="8" maxlength="72" placeholder="至少8个字符" :disabled="busy"/><button type="button" :aria-label="show?'隐藏密码':'显示密码'" :aria-pressed="show" @click="show=!show">{{ show?'隐藏':'显示' }}</button></span></label><p v-if="error" class="form-error" role="alert">{{ error }}</p><button class="primary" type="submit" :disabled="busy">{{ busy?'请稍候…':mode==='register'?'创建账号':'登录' }}<AppIcon name="arrow-right" :size="17"/></button><button type="button" class="text-action" :disabled="busy" @click="mode=mode==='login'?'register':'login';error=''">{{ mode==='login'?'还没有账号？注册账号':'已有账号，前往登录' }}</button></form><p class="account-note">当前使用用户名与密码账户，房源均为模拟数据。</p></main></template>
<style scoped>.account-page{max-width:480px;margin:auto;padding-top:40px}.account-heading{margin-bottom:36px}.account-heading h1{font-size:30px;line-height:1.5;letter-spacing:-.03em;margin:8px 0 14px}.account-heading>p:last-child{font-size:14px;color:var(--muted)}.password-input{display:flex;background:var(--surface);border-radius:12px;overflow:hidden}.password-input input{background:transparent;flex:1;min-width:0}.password-input button{min-width:58px;min-height:48px;font-size:12px;flex-shrink:0}.account-note{font-size:12px;line-height:1.8;color:var(--muted);margin-top:34px;text-align:center}</style>
